import{c as e,J as a,h as l,k as r}from"./chunks/framework.WgZQdPFo.js";const g=JSON.parse('{"title":"Обзор и философия капитала","description":"Концепция единого финансового контура мастера, разделение кармана мастера и кассы цеха, автоматический расчет личных расходов через дельту капитала.","frontmatter":{"title":"Обзор и философия капитала","description":"Концепция единого финансового контура мастера, разделение кармана мастера и кассы цеха, автоматический расчет личных расходов через дельту капитала.","order":16},"headers":[],"relativePath":"ru/docs/spaces/moy-kapital/overview.md","filePath":"ru/docs/spaces/moy-kapital/overview.md"}'),o={name:"ru/docs/spaces/moy-kapital/overview.md"};function s(i,t,n,d,p,h){return a(),l("div",null,[...t[0]||(t[0]=[r('<h1 id="обзор-и-философия-пространства-«мои-капитал»" tabindex="-1">Обзор и философия пространства «Мой капитал» <a class="header-anchor" href="#обзор-и-философия-пространства-«мои-капитал»" aria-label="Permalink to &quot;Обзор и философия пространства «Мой капитал»&quot;">​</a></h1><p>Каждый ремесленник и владелец небольшого производства рано или поздно сталкивается с одной и той же дилеммой: где заканчиваются деньги мастерской и начинаются личные средства семьи?</p><p>Если смешивать закупку кожи, оплату аренды мастерской и покупку продуктов в одном кошельке, бизнес теряет прозрачность. Становится невозможно понять, приносит ли мастерская реальную чистую прибыль или держится на плаву только за счет постоянных личных вливаний.</p><p>Пространство <strong>«Мой капитал»</strong> в составе ПРО-режима ОмниКрафт ЕРП создано как раз для того, чтобы навести идеальный порядок на границе между бизнесом и личной жизнью, не превращая мастера в уставшего бухгалтера с кипой кассовых чеков.</p><hr><h2 id="принцип-двух-контуров-цех-и-карман-мастера" tabindex="-1">Принцип двух контуров: цех и карман мастера <a class="header-anchor" href="#принцип-двух-контуров-цех-и-карман-мастера" aria-label="Permalink to &quot;Принцип двух контуров: цех и карман мастера&quot;">​</a></h2><p>Финансовая модель ОмниКрафт ЕРП разделяет потоки денег на два строгих контура:</p><ol><li><strong>Операционный контур цеха (Рабочие пространства):</strong> учет сырья на складе, калькуляция себестоимости, движение заказов на верстаке, движение денег по кассе мастерской (ДДС) и склад готовой продукции.</li><li><strong>Консолидированный контур капитала (Пространство «Мой капитал»):</strong> совокупная стоимость всех активов владельца, включая личные банковские карты, сбережения, инвестиционный портфель, оборудование, недвижимость и доли в каждом из производственных пространств.</li></ol><div class="info custom-block"><p class="custom-block-title">Независимость баз данных</p><p>Личные финансы хранятся в изолированной базе данных <code>personal_finance.db</code>. Это гарантирует, что данные о личных счетах, инвестициях и имуществе никогда не попадут в производственные отчеты конкретного цеха и останутся строго конфиденциальными.</p></div><hr><h2 id="математическая-дельта-учет-трат-без-сбора-чеков" tabindex="-1">Математическая дельта: учет трат без сбора чеков <a class="header-anchor" href="#математическая-дельта-учет-трат-без-сбора-чеков" aria-label="Permalink to &quot;Математическая дельта: учет трат без сбора чеков&quot;">​</a></h2><p>Главная инженерная находка пространства «Мой капитал» — <strong>метод расчета расходов по балансовой дельте</strong>.</p><p>Большинство программ для личных финансов требуют дисциплины робота: нужно каждый день открывать телефон и вручную заносить траты на кофе, бензин, хлеб и оплату интернета. На практике мастера хватает максимум на две недели, после чего учет забрасывается.</p><p>В ОмниКрафт ЕРП применен обратный инженерный подход:</p><p>$$\\text{Личные расходы за период} = \\text{Капитал на начало} + \\text{Доходы цеха и личные дивиденды} - \\text{Капитал на конец}$$</p><p>Вам достаточно раз в неделю или в конце месяца актуализировать остатки на нескольких основных карточках и вкладах. Программа автоматически сопоставит полученную дельту с зафиксированными операциями мастерской и вычислит точную сумму, которая ушла на личную жизнь.</p><div class="tip custom-block"><p class="custom-block-title">Спокойный сон предпринимателя</p><p>Если баланс личных счетов за месяц вырос, а чистая прибыль мастерской подтверждена движением готовой продукции и продажами, ваше дело развивается в плюс. Если же остатки тают, система подсветит непривязанный отток средств до того, как образуется кассовый разрыв.</p></div><hr><h2 id="архитектура-пространства-«мои-капитал»" tabindex="-1">Архитектура пространства «Мой капитал» <a class="header-anchor" href="#архитектура-пространства-«мои-капитал»" aria-label="Permalink to &quot;Архитектура пространства «Мой капитал»&quot;">​</a></h2><p>Интерфейс пространства организован в виде логичной 5-ступенчатой системы:</p><ul><li><strong>Счета и инвестиции:</strong> единый центр управления ликвидными деньгами. Включает две вкладки: «Счета и кошельки» (наличные, дебетовые карты, вклады, расчетная валюта и стейблкоины) и «Инвестиционный портфель» (акции, облигации, займы, доли в бизнесе).</li><li><strong>Имущество и ресурсы:</strong> материальные активы долгосрочного пользования (оборудование вне цеха, станки в долевом владении, недвижимость, автотранспорт).</li><li><strong>Личные операции:</strong> журнал крупных личных поступлений и внеплановых изъятий, влияющих на общий баланс.</li><li><strong>Сводка капитала:</strong> контрольная панель Net Worth, собирающая воедино личные активы и производственный капитал всех подключенных мастерских.</li><li><strong>Аналитика капитала:</strong> графики динамики благосостояния, валютная корзина и распределение активов по классам.</li></ul><hr><h2 id="панель-инструментов-верхнего-уровня" tabindex="-1">Панель инструментов верхнего уровня <a class="header-anchor" href="#панель-инструментов-верхнего-уровня" aria-label="Permalink to &quot;Панель инструментов верхнего уровня&quot;">​</a></h2><p>В верхней правой части окна «Мой капитал» расположена панель быстрых действий:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Кнопка</th><th style="text-align:left;">Назначение</th><th style="text-align:left;">Действие</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>📊 Статистика</strong></td><td style="text-align:left;">Структура и распределение</td><td style="text-align:left;">Открывает боковую шторку или модальное окно с интерактивными графиками валютной корзины и классов активов.</td></tr><tr><td style="text-align:left;"><strong>💱 Курсы</strong></td><td style="text-align:left;">Централизованный валютный справочник</td><td style="text-align:left;">Позволяет в один клик скорректировать биржевые курсы или импортировать их из нейросети без платных API.</td></tr><tr><td style="text-align:left;"><strong>⚙️ Настройки</strong></td><td style="text-align:left;">Конфигурация пространства</td><td style="text-align:left;">Выбор формата отображения статистики (боковая панель / модальный диалог) и управление справочниками.</td></tr><tr><td style="text-align:left;"><strong>📖 Справка</strong></td><td style="text-align:left;">Контекстное руководство</td><td style="text-align:left;">Мгновенно открывает страницу документации именно по той вкладке, на которой Вы сейчас находитесь.</td></tr></tbody></table><hr><h2 id="безопасность-и-zero-api-подход" tabindex="-1">Безопасность и Zero-API подход <a class="header-anchor" href="#безопасность-и-zero-api-подход" aria-label="Permalink to &quot;Безопасность и Zero-API подход&quot;">​</a></h2><p>Вся финансовая информация обрабатывается <strong>строго на Вашем компьютере</strong>. Программа не отправляет балансы карт, суммы инвестиций или списки счетов на сторонние сервера или облачные платформы.</p><p>Обновление валютных курсов работает без привязки к платным внешним API: вы можете отредактировать курс любой валюты за две секунды вручную либо скопировать сгенерированный программой промпт в любую бесплатную языковую модель (ChatGPT, Claude, DeepSeek) и вставить ответ одной кнопкой.</p>',29)])])}const f=e(o,[["render",s]]);export{g as __pageData,f as default};
